def _pgvector_wanted(bind) -> bool:
    import os

    return bind.dialect.name == "postgresql" and os.environ.get("RAGOPS_VECTOR_BACKEND", "auto") != "json"


def _to_pgvector() -> None:
    """v0.5 moved embeddings from JSON to pgvector vector(N) columns with HNSW indexes (when the extension exists)."""
    import os

    bind = op.get_bind()
    if not _pgvector_wanted(bind):
        return
    try:
        with bind.begin_nested():
            bind.exec_driver_sql("CREATE EXTENSION IF NOT EXISTS vector")
    except Exception:  # noqa: BLE001 - extension unavailable: keep JSON columns (RAGOps falls back automatically)
        if os.environ.get("RAGOPS_VECTOR_BACKEND") == "pgvector":
            raise
        return
    dim = int(os.environ.get("RAGOPS_EMBEDDING_DIM", "384"))
    for table, col in (("chunks", "embedding"), ("traces", "query_embedding")):
        bind.exec_driver_sql(f"ALTER TABLE {table} ALTER COLUMN {col} TYPE vector({dim}) "
                             f"USING CASE WHEN {col} IS NULL THEN NULL ELSE ({col}::text)::vector({dim}) END")
        bind.exec_driver_sql(f"CREATE INDEX IF NOT EXISTS ix_{table}_{col}_hnsw ON {table} "
                             f"USING hnsw ({col} vector_cosine_ops)")


